<script lang="ts">
import {onMount,onDestroy} from 'svelte';import type {InPageNavigationContract} from '@unofficial-krds/contracts';import {owned,ignoredKey} from './catalog-state.svelte.js';
let p:InPageNavigationContract=$props();const uid=$props.id();let expanded=$state(false),active=$state('');let keyboardId:string|undefined;let rebind=()=>{};const blurCleanups=new Set<()=>void>();
function flatten(items:typeof p.sections):typeof p.sections{return items.flatMap(item=>[item,...flatten(item.children??[])]);}
$effect(()=>{p.sections;rebind();});
onMount(()=>{const watched=new Map<string,Element>();const observer=new IntersectionObserver(entries=>{const found=entries.find(entry=>entry.isIntersecting);if(found&&found.target.id!==(p.activeId??active)){active=found.target.id;p.onActiveChange?.({id:active,reason:'scroll'});}},{rootMargin:'-10% 0px -70% 0px'});rebind=()=>{const wanted=new Map(flatten(p.sections).map(item=>[item.id,document.getElementById(item.id)]).filter((entry):entry is[string,HTMLElement]=>!!entry[1]));for(const[id,node]of watched)if(wanted.get(id)!==node){observer.unobserve(node);watched.delete(id);}for(const[id,node]of wanted)if(watched.get(id)!==node){observer.observe(node);watched.set(id,node);}};const mutations=new MutationObserver(rebind);mutations.observe(document.body,{childList:true,subtree:true});rebind();return()=>{rebind=()=>{};observer.disconnect();mutations.disconnect();};});
onDestroy(()=>{for(const cleanup of blurCleanups)cleanup();});
function activate(e:MouseEvent,id:string,keyboard=false){if(e.button>0||e.metaKey||e.ctrlKey||e.shiftKey||e.altKey)return;const target=document.getElementById(id);if(!target)return;e.preventDefault();if(!keyboard&&e.detail>0)(e.currentTarget as HTMLElement|null)?.focus();if(keyboard||e.detail===0){const before=target.getAttribute('tabindex');if(target.tabIndex<0)target.tabIndex=-1;target.focus();if(before===null){const cleanup=()=>{target.removeAttribute('tabindex');target.removeEventListener('blur',cleanup);blurCleanups.delete(cleanup);};blurCleanups.add(cleanup);target.addEventListener('blur',cleanup,{once:true});}}target.scrollIntoView({behavior:'instant'});if((p.activeId??active)!==id){active=id;p.onActiveChange?.({id,reason:'activation'});}}
</script>
<nav aria-label={p.title??'이 페이지의 구성'} {...owned('in-page-navigation','root',expanded?'expanded':'collapsed')}><h2 {...owned('in-page-navigation','title')}>{p.title??'이 페이지의 구성'}</h2>{#if p.narrowMode==='disclosure'}<button type="button" {...owned('in-page-navigation','disclosure-trigger',expanded?'expanded':'collapsed')} aria-expanded={expanded} aria-controls={uid} onclick={()=>expanded=!expanded}>{expanded?'구성 접기':'구성 펼치기'}</button>{/if}
{#snippet list(items:typeof p.sections,root=false)}<ul id={root?uid:undefined} hidden={root&&p.narrowMode==='disclosure'&&!expanded} {...owned('in-page-navigation','list',expanded?'expanded':'collapsed')}>{#each items as item(item.id)}<li {...owned('in-page-navigation','item',(p.activeId??active)===item.id&&'active')}><a href={`#${item.id}`} aria-current={(p.activeId??active)===item.id?'location':undefined} {...owned('in-page-navigation','link',(p.activeId??active)===item.id&&'active')} onclick={event=>{const keyboard=keyboardId===item.id;keyboardId=undefined;activate(event,item.id,keyboard);}} onpointerdown={()=>keyboardId=undefined} onblur={()=>keyboardId=undefined} onkeyup={()=>keyboardId=undefined} onkeydown={event=>{if(ignoredKey(event))return;if(event.key==='Enter')keyboardId=item.id;if(event.key===' '){event.preventDefault();activate(new MouseEvent('click',{detail:0}),item.id,true);}}}>{item.label}</a>{#if item.children?.length}{@render list(item.children)}{/if}</li>{/each}</ul>{/snippet}{@render list(p.sections,true)}</nav>
